// Function to create a 3D rotation matrix around the Y-axis
mat3 rotateY(float angle) {
    float c = cos(angle);
    float s = sin(angle);
    return mat3(
        c, 0.0, s,
        0.0, 1.0, 0.0,
        -s, 0.0, c
    );
}

// Function to apply a simple blur effect (for tunnel vision)
vec3 blur(vec2 uv, float radius, samplerCube tex, mat3 rotation) {
    vec3 color = vec3(0.0);
    float samples = 16.0; // Number of samples for the blur
    float angleIncrement = 6.28318530718 / samples; // 2 * PI / samples

    for (float i = 0.0; i < samples; i++) {
        float angle = i * angleIncrement;
        vec2 offset = vec2(cos(angle), sin(angle)) * radius;
        vec3 dir = vec3(uv + offset, 1.0); // Direction vector for cubemap sampling
        dir = normalize(dir);
        dir = rotation * dir; // Apply rotation
        color += texture(tex, dir).rgb; // Sample the cubemap and extract RGB
    }

    return color / samples; // Average the samples
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Normalize coordinates to [-1, 1] for cubemap sampling
    vec2 uv = fragCoord / iResolution.xy * 2.0 - 1.0;

    // Mouse position (gaze position) normalized to [-1, 1]
    vec2 gazePos = iMouse.xy / iResolution.xy * 2.0 - 1.0;

    // Scotoma type (0 = Tunnel Vision, 1 = Central, 2 = Hemianopic)
    int scotomaType = 0; // Change this to switch between scotoma types

    // Calculate distance from the gaze position
    float dist = length(uv - gazePos);

    // Circular panning: Rotate the camera around the Y-axis over time
    float time = iTime * 0.5; // Adjust speed of panning
    mat3 rotation = rotateY(time); // Create a 3D rotation matrix around the Y-axis

    // Sample the cubemap (environment map)
    vec3 dir = vec3(uv, 1.0); // Direction vector for cubemap sampling
    dir = normalize(dir);     // Normalize the direction vector
    dir = rotation * dir;     // Apply Y-axis rotation to the direction vector
    vec3 envColor = texture(iChannel0, dir).rgb; // Sample the cubemap

    // Initialize blending factor
    float t = 1.0;

    // Apply scotoma based on type
    if (scotomaType == 0) {
        // Tunnel Vision (Blurry Periphery)
        float tunnelRadius = 0.8; // Radius of the clear gaze area
        float feather = 0.1;      // Feathering for smooth transition
        float blurIntensity = 0.05; // Intensity of the blur

        // Calculate blending factor for smooth transition
        t = smoothstep(tunnelRadius - feather, tunnelRadius + feather, dist);

        // Apply blur only outside the tunnel radius
        vec3 blurredColor = blur(uv, blurIntensity, iChannel0, rotation); // Apply blur
        envColor = mix(envColor, blurredColor, t); // Blend between clear and blurry

        fragColor = vec4(envColor, 1.0);
    } else if (scotomaType == 1) {
        // Central Scotoma
        float scotomaSize = 0.2;              // Size of the scotoma (radius)
        float scotomaFeather = 0.05;          // Feathering around the scotoma
        vec3 scotomaColor = vec3(1.0); // Color of the scotoma
        t = smoothstep(scotomaSize - scotomaFeather, scotomaSize + scotomaFeather, dist);

        // Blend between the environment map and the scotoma color
        vec3 finalColor = mix(scotomaColor, envColor, t);

        // Output the final color (fully opaque)
        fragColor = vec4(finalColor, 1.0);
    } else if (scotomaType == 2) {
        // Hemianopic Scotoma (Left Half)
        float feather = 0.3;
        vec3 scotomaColor = vec3(1.0); // Color of the scotoma
        t = smoothstep(0.0, feather, uv.x);
        // Blend between the environment map and the scotoma color
        vec3 finalColor = mix(scotomaColor, envColor, t);

        // Output the final color (fully opaque)
        fragColor = vec4(finalColor, 1.0);
    }
}
